import axios from "axios";

import { queryClient } from "../lib/queryClient";

// Глобальный axios-клиент: одноимённый origin (см. §17.1 — Web Service отдаёт
// и API, и SPA из одного бинаря), куки автоматически прикрепляются.
const axiosInstance = axios.create({
  withCredentials: true,
  timeout: 30_000,
  headers: { "Content-Type": "application/json" },
});

// На 401 редиректим на /login глобально (см. §17.6 ТЗ). Перед редиректом
// чистим react-query-кеш: следующий логин (возможно, другим пользователем
// или с другой текущей командой) не должен видеть прежние данные (Phase AUD.6).
axiosInstance.interceptors.response.use(
  (r) => r,
  (err) => {
    if (err?.response?.status === 401 && location.pathname !== "/login") {
      queryClient.clear();
      location.href = "/login";
    }
    return Promise.reject(err);
  },
);

// isNotFound — ошибка запроса означает 404. Узел/ресурс чужой команды (§18)
// неотличим от несуществующего by design (не утекает факт существования),
// поэтому UI разбирает именно 404.
export function isNotFound(error: unknown): boolean {
  return (error as { response?: { status?: number } })?.response?.status === 404;
}

// attachmentName — имя файла из Content-Disposition: attachment; filename="…".
export function attachmentName(header: unknown): string | undefined {
  if (typeof header !== "string") return undefined;
  const m = /filename="?([^";]+)"?/i.exec(header);
  return m?.[1];
}

// parseBlobError — с responseType "blob" axios и тело ошибки отдаёт blob'ом:
// разбираем его обратно в JSON, чтобы вызывающий читал response.data.error
// как у остальных запросов. Возвращает ту же ошибку для throw.
async function parseBlobError(e: unknown): Promise<unknown> {
  const res = (e as { response?: { data?: unknown } }).response;
  if (res?.data instanceof Blob) {
    try {
      res.data = JSON.parse(await res.data.text());
    } catch {
      // Не JSON (обрыв прокси, HTML-страница ошибки) — оставляем как есть,
      // вызывающий покажет общую ошибку.
    }
  }
  return e;
}

export const api = {
  // opts.signal — настоящая отмена HTTP-запроса (§77.3): react-query передаёт
  // AbortSignal в queryFn, и без проброса в axios отмена оставалась бы чисто
  // клиентской — ClickHouse продолжал бы молотить дорогой полнотекстовый
  // запрос. Разрыв соединения отменяет c.Request.Context() хендлера, и
  // clickhouse-go снимает запрос на сервере.
  async get<T>(
    url: string,
    params?: Record<string, unknown>,
    opts?: { signal?: AbortSignal },
  ): Promise<T> {
    const r = await axiosInstance.get<T>(url, { params, signal: opts?.signal });
    return r.data;
  },
  // opts.params — query-параметры POST-запроса. Нужны там, где фильтр приходит
  // теми же параметрами, что у соответствующего GET (§85: фильтр журнала
  // разбирает общий с ним logQueryFromContext), а в теле лежит только состояние
  // операции. opts.signal — настоящая отмена (кнопка «Остановить» цикла батчей).
  // opts.timeout — свой потолок вместо общих 30 с: восстановление §110 создаёт
  // сотни таблиц ClickHouse, и обрыв по таймауту клиента показал бы ошибку
  // там, где сервер ещё работает.
  async post<T>(
    url: string,
    body?: unknown,
    opts?: { params?: Record<string, unknown>; signal?: AbortSignal; timeout?: number },
  ): Promise<T> {
    const r = await axiosInstance.post<T>(url, body, {
      params: opts?.params,
      signal: opts?.signal,
      timeout: opts?.timeout,
    });
    return r.data;
  },
  // postBlob — POST с файлом в ответе (§110: выгрузка резервной копии).
  // Пароль уходит телом, поэтому обычная ссылка не годится. С responseType
  // "blob" axios и ошибку отдаёт blob'ом — разбираем её обратно в JSON, чтобы
  // вызывающий читал response.data.error/code как у остальных запросов.
  async postBlob(url: string, body?: unknown): Promise<{ blob: Blob; filename?: string }> {
    try {
      const r = await axiosInstance.post<Blob>(url, body, { responseType: "blob" });
      return { blob: r.data, filename: attachmentName(r.headers["content-disposition"]) };
    } catch (e) {
      throw await parseBlobError(e);
    }
  },
  // getBlob — GET с файлом в ответе (§115: выгрузка журнала в Excel). Файл
  // идёт потоком минутами, поэтому общий потолок 30 с снят (timeout: 0 —
  // без ограничения): каждый запрос в ClickHouse ограничен сервером, а
  // «Остановить» — opts.signal. onDownloadProgress — сколько байт уже пришло
  // (длины заранее нет: файл пишется по мере чтения журнала). opts.headers —
  // например Accept-Language: язык листов файла должен совпадать с языком
  // интерфейса, а не браузера.
  async getBlob(
    url: string,
    params?: Record<string, unknown>,
    opts?: {
      signal?: AbortSignal;
      headers?: Record<string, string>;
      onDownloadProgress?: (loaded: number) => void;
    },
  ): Promise<{ blob: Blob; filename?: string }> {
    const onProgress = opts?.onDownloadProgress;
    try {
      const r = await axiosInstance.get<Blob>(url, {
        params,
        signal: opts?.signal,
        headers: opts?.headers,
        responseType: "blob",
        timeout: 0,
        onDownloadProgress: onProgress ? (e) => onProgress(e.loaded) : undefined,
      });
      return { blob: r.data, filename: attachmentName(r.headers["content-disposition"]) };
    } catch (e) {
      throw await parseBlobError(e);
    }
  },
  async put<T>(url: string, body?: unknown): Promise<T> {
    const r = await axiosInstance.put<T>(url, body);
    return r.data;
  },
  async patch<T>(url: string, body?: unknown): Promise<T> {
    const r = await axiosInstance.patch<T>(url, body);
    return r.data;
  },
  async del(url: string): Promise<void> {
    await axiosInstance.delete(url);
  },
};

export type RootMethod = "request" | "requestAsync" | "RabbitMQAsync";
// §40: ANY — узел принимает любой метод (входящий) либо зеркалит входящий
// (исходящий). Сервер отдаёт его как есть, и без него тип врал бы.
export type HTTPMethod = "GET" | "POST" | "PUT" | "DELETE" | "ANY";

// §27: runtime-health Puller-воркера узла RabbitMQAsync (только для него).
export type RMQStatus = {
  degraded: boolean;
  reason?: string;
  connection_state: "down" | "connecting" | "up";
  queue_depth: number;
  consumer_count: number;
  attempts: number;
  since?: string;
};

export type Node = {
  id: string;
  // §18: команда-владелец узла (UUID). Имя резолвится по членствам
  // (GET /api/me/teams) — эндпоинт узла отдаёт только идентификатор.
  team_id: string;
  path: string;
  root_method: RootMethod;
  incoming_method?: HTTPMethod;
  outgoing_method?: HTTPMethod;
  url_mode: "static" | "from_request";
  target_url: string;
  // §39: path-passthrough — приклеивать хвост входящего пути к target URL.
  path_passthrough?: boolean;
  // §107.2: GET-подписка SSE получает 405 от Nexus (только request).
  sse_decline?: boolean;
  status: "enabled" | "disabled" | "paused";
  auth_type: string;
  // §41: динамическая авторизация (исходящая token/basic_from_request).
  auth_dynamic_source?: string;
  auth_dynamic_field?: string;
  auth_dynamic_strip_prefix?: string;
  // §41: динамическая авторизация на входе (источник+поле для token/basic).
  incoming_auth_dynamic_source?: string;
  incoming_auth_dynamic_field?: string;
  // §55.6: сами креды наружу не отдаются никогда — только признаки *_set.
  incoming_auth_type?: string;
  auth_credentials_set?: boolean;
  incoming_auth_credentials_set?: boolean;
  // Логин basic-кредов (часть до первого «:») — не секрет, в отличие от
  // пароля; отдаётся только при типе basic (prefill формы + просмотр узла).
  auth_login?: string;
  incoming_auth_login?: string;
  // §16: имя заголовка с HMAC-подписью (incoming_auth_type=webhook_signature).
  webhook_signature_header?: string;
  // Таймаут вызова target и ретраи — показываются в просмотре узла (ConfigTab).
  timeout_ms?: number;
  retry_count?: number;
  retry_backoff_ms?: number;
  clickhouse_table: string;
  clickhouse_template_id: string;
  // §64: таблицей логов управляет не Nexus (оператор или посторонний писатель).
  external_table: boolean;
  // §84.4: чем считается пустое «от» в произвольном периоде — старше этой
  // глубины записей физически нет, их удалил TTL.
  clickhouse_retention_days?: number;
  forward_headers: string[];
  log_request_body: boolean;
  log_response_body: boolean;
  log_headers: boolean;
  logging_enabled: boolean;
  max_body_size_enabled: boolean;
  max_body_size: number;
  // §36: авто-репроцессор DLQ — TTL повтора и минимальная задержка между повторами (сек).
  dlq_ttl_seconds?: number;
  dlq_retry_delay_seconds?: number;
  // §81.3: политика защиты узла. 0/отсутствие = «как в конфигурации сервиса».
  circuit_breaker_threshold?: number;
  circuit_breaker_cooldown_sec?: number;
  // §107.3: таймаут при установленном соединении не засчитывается защите.
  breaker_ignore_timeouts?: boolean;
  // §29: произвольный комментарий-описание узла.
  comment?: string;
  // §99: группа узла для группировки списка. Пусто/отсутствие = «без группы».
  group_id?: string;
  // §83: шаблон ответа приёма. null/отсутствие — шина отвечает как раньше.
  async_ack_spec?: AckSpec | null;
  // §27: RabbitMQAsync (пустые/нулевые для request/requestAsync).
  rmq_host?: string;
  rmq_port?: number;
  rmq_vhost?: string;
  rmq_user?: string;
  rmq_password_set?: boolean;
  rmq_queue?: string;
  rmq_use_tls?: boolean;
  pull_interval_sec?: number;
  pull_batch_size?: number;
  pull_prefetch?: number;
  rmq_status?: RMQStatus;
  created_at: string;
  updated_at: string;
  // §63: логин автора создания и последнего изменения узла. Пусто у узлов до
  // миграции 0026 (в UI показывается «—»).
  created_by?: string;
  updated_by?: string;
};

// §83: спека ответа приёма. status=0 — «как сейчас» (200, либо 202 у узла на
// паузе); допустимы только 2xx. Пустой content_type/on_error бэкенд заполняет
// дефолтами.
export type AckSpec = {
  version: number;
  status?: number;
  content_type: "application/json" | "text/plain";
  body: string;
  on_error: "default" | "error";
};

// §83: ответ POST /api/nodes/ack-preview. Провал подстановки приходит с
// HTTP 200 и ok=false — это результат проверки, а не ошибка запроса.
export type AckPreviewResult = {
  ok: boolean;
  status?: number;
  content_type?: string;
  body?: string;
  reason?: string;
  placeholder?: string;
  message?: string;
};

// §27: ответ POST /api/nodes/test-rmq.
export type RMQTestCheck = {
  ok: boolean;
  elapsed_ms: number;
  error?: string;
  message_count?: number;
  consumer_count?: number;
};
export type RMQTestResult = {
  ok: boolean;
  checks: { connect: RMQTestCheck; auth: RMQTestCheck; queue: RMQTestCheck };
};

