// §21: метрики панели (см. /api/metrics/*).
export type OverviewKPI = {
  incoming_24h: number;
  outgoing_24h: number;
  kafka_queue: number;
  errors_24h: number;
  error_rate: number;
  prometheus_available: boolean;
};
export type NodeThroughput = {
  // §86.7: строки сшиваются с узлами по node_id, а не по node (пути): путь
  // уникален лишь внутри команды, и в сквозном режиме два узла разных команд
  // могут иметь одинаковый. Поле может быть пустым у старого бэкенда.
  node_id?: string;
  node: string;
  in: number;
  out: number;
  errors: number;
  p95_ms: number;
  spark: number[];
  // Ошибки в тех же бакетах, что и spark (§52-доп): столбец спарклайна рисуется
  // двухцветным по доле ошибок. Пустой/отсутствующий ряд = разбивки нет
  // (старый бэкенд или Prometheus-fallback) — тогда столбец одноцветный.
  spark_err?: number[];
  // §41 (back-compat, = last_outcome != "ok"): UI использует last_outcome.
  last_error: boolean;
  // §52: исход последнего исходящего вызова узла — ok (2xx) / degraded
  // (ответил не-2xx <500) / down (транспортная ошибка или 5xx).
  last_outcome: "ok" | "degraded" | "down";
};
// §44.A: totals = СУММА строк items за выбранный период (CH, уникальные
// запросы). KPI шапки берёт incoming/outgoing/errors отсюда → шапка сходится
// с таблицей. error_rate = errors/incoming (0..1).
export type OverviewTotals = {
  incoming: number;
  outgoing: number;
  errors: number;
  error_rate: number;
};
export type NodesThroughputResp = {
  items: NodeThroughput[];
  totals: OverviewTotals;
  prometheus_available: boolean;
};
// §86.10: лёгкая строка среза — по ней строится порядок узлов и бейдж статуса
// ДО того, как доедут порционные метрики. Без p95 и спарклайна: срез приходит
// на ВСЕ узлы скоупа, и каждое лишнее поле умножается на их число.
export type NodeRank = {
  node_id: string;
  in: number;
  out: number;
  errors: number;
  last_outcome: "ok" | "degraded" | "down";
};
// §86.4: агрегат шапки отдельным запросом (GET /api/metrics/totals). Нужен
// сквозному режиму: там строки таблицы грузятся порционно, и шапка обязана
// считаться по всему скоупу, иначе её значение зависело бы от прокрутки.
// §86.10: тем же ответом едет срез nodes — он считается тем же проходом.
// Опционален: старый бэкенд поля не отдаёт, и рабочий стол обязан это пережить.
export type NodesTotalsResp = { totals: OverviewTotals; nodes?: NodeRank[] };
// §79.5: chart_unit — как посчитаны столбцы.
//   records  — запись в интервале своего прихода, «ошибка» по ИТОГОВОМУ статусу
//              (после успешного повтора красный сегмент исчезает сам);
//   attempts — деградация на больших окнах: запись в интервале своего прогона.
export type ChartUnit = "records" | "attempts";

export type LatencyPointResp = { ts: number; p50_ms: number; p95_ms: number; attempts: number };

export type NodeMetricsResp = {
  kpi: {
    total: number;
    delivered: number;
    errors: number;
    p95_ms: number;
    p99_ms: number;
    // §84.6: последняя активность В ОКНЕ и под текущими фильтрами (UnixMilli);
    // 0 = запросов не было. Опционально — старый бэкенд поля не отдаёт.
    last_seen_ms?: number;
  };
  series: { ts: number; count: number; errors: number }[];
  chart_available: boolean;
  range_ms: number;
  // §79.5: фактическая ширина столбца (может отличаться от запрошенного шага —
  // он согласуется с окном) и единица счёта столбцов.
  step_seconds?: number;
  chart_unit?: ChartUnit;
  // §84.5: ряд латентности по тем же интервалам. Оба поля опциональны —
  // совместимость в обе стороны: новый фронт со старым бэкендом их просто не
  // увидит, а не сломается.
  latency?: LatencyPointResp[];
  latency_available?: boolean;
  // §102: рейтинг подпутей (колонка method) за то же окно и под теми же
  // фильтрами. Приезжает только по флагу with_methods=1 — «Обзор» его не
  // просит. Все три поля опциональны: старый бэкенд их не отдаёт.
  //   methods           — до MethodsLimit строк, total DESC;
  //   methods_available — источник ответил (false = деградация карточки);
  //   methods_truncated — методов больше, чем влезло в лимит.
  methods?: MethodStatResp[];
  methods_available?: boolean;
  methods_truncated?: boolean;
};

// §102: строка рейтинга «Запросы по методам». Единица — ЗАПИСЬ (уникальный ID),
// как в kpi: именно поэтому Σ(total) сходится с kpi.total и строку «Остальные»
// можно вычесть на клиенте, не запрашивая отдельно.
export type MethodStatResp = { method: string; total: number; delivered: number };

